document.querySelectorAll('[data-lab="L02-I1"]').forEach(root=>{if(root.dataset.ready)return;root.dataset.ready='1';const s=root.querySelector('[data-x]'),o=root.querySelector('[data-readout]'),p=root.querySelector('[data-dot]'),e=root.querySelector('[data-explain]'),en=root.dataset.lang==='en';function update(){const xu=Number(s.value),ix=Math.floor((xu+20)/40),x=xu-ix*40;o.textContent=' xᵤ = '+xu.toFixed(1)+'; x = '+x.toFixed(1)+'; iₓ = '+ix;p.setAttribute('cx',100+(x+20)*15);e.textContent=(en?'Reconstruction: ':'接回路径：')+x.toFixed(1)+' + ('+ix+') × 40 = '+xu.toFixed(1)+(en?'. The mapping joins periodic images into a continuous coordinate.':'。周期映像通过这一关系接成连续坐标。');}s.addEventListener('input',update);root.querySelector('[data-reset]').addEventListener('click',()=>{s.value='19.8';update();});update();});